*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDINS30400.xml";
scwin.ckb1 = "N";
scwin.ckb2 = "N";
scwin.ckb3 = "N";
scwin.ckb4 = "N";
scwin.ckb5 = "N";
scwin.ckb6 = "N";
scwin.ckb7 = "N";
scwin.ckb8 = "N";
scwin.ckb9 = "N";
scwin.ckb10 = "N";
scwin.ckb11 = "N";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/********************************************** 
 * 함수명   : ins_search
 * 설명       : 삭제 내역 조회 
 ***********************************************/
scwin.ins_search = function() {
    // 코드삭제일 체크
    if ($c.stf.compareFromToDate2(edt_SDEL_DD, edt_EDEL_DD) == false) {
        return false;
    }
    scwin.fn_setCheckBox();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS30400_T_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.search.select.listDelCdListInquiry" + "&{P}STD_CD=" + txb_STD_CD.getValue() + "&{P}ISUR_CD=" + txb_ISUR_CD.getValue() + "&{P}SDEL_DD=" + edt_SDEL_DD.getValue() + "&{P}EDEL_DD=" + edt_EDEL_DD.getValue() + "&{P}PARAM1=" + scwin.ckb1 + "&{P}PARAM2=" + scwin.ckb2 + "&{P}PARAM3=" + scwin.ckb3 + "&{P}PARAM4=" + scwin.ckb4 + "&{P}PARAM5=" + scwin.ckb5 + "&{P}PARAM6=" + scwin.ckb6 + "&{P}PARAM7=" + scwin.ckb7 + "&{P}PARAM8=" + scwin.ckb8 + "&{P}PARAM9=" + scwin.ckb9 + "&{P}PARAM10=" + scwin.ckb10 + "&{P}PARAM11=" + scwin.ckb11 + "&{P}PARAM12=" + ckb12;

    //	 alert( url);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};

/********************************************** 
 * 함수명   : fn_setCheckBox
 * 설명       : CHECKB 박스 값을 정의한다.
 ***********************************************/
scwin.fn_setCheckBox = function() {
    /*ckb1주권1 ckb_2채권  ckb_3ELS/DLS ckb_4수익증권 ckb_5 신주인수권증권 ckb_6유가증권예탁증서(DR)
		ckb_7전자단기사채/CP ckb_8스트립 ckb_9양도성예금증서(CD) ckb_10주식워런트증권(ELW)    ckb_11 ETN     ckb_12 투자계약증권
	*/
    scwin.ckb1 = $c.stf.getObjectValue(ckb_1);
    scwin.ckb2 = $c.stf.getObjectValue(ckb_2);
    scwin.ckb3 = $c.stf.getObjectValue(ckb_3);
    scwin.ckb4 = $c.stf.getObjectValue(ckb_4);
    scwin.ckb5 = $c.stf.getObjectValue(ckb_5);
    scwin.ckb6 = $c.stf.getObjectValue(ckb_6);
    scwin.ckb7 = $c.stf.getObjectValue(ckb_7);
    scwin.ckb8 = $c.stf.getObjectValue(ckb_8);
    scwin.ckb9 = $c.stf.getObjectValue(ckb_9);
    scwin.ckb10 = $c.stf.getObjectValue(ckb_10);
    scwin.ckb11 = $c.stf.getObjectValue(ckb_11);
    ckb12 = $c.stf.getObjectValue(ckb_12);
};


/********************************************** 
 * 함수명   : fn_ChkValid
 * 설명       : 조회 조건을 체크한다..... 체크박스는 한개이상 서택하여야 한다.
 ***********************************************/
scwin.fn_ChkValid = function() {
    scwin.ckb1 = $c.stf.getObjectValue(ckb_1);
    scwin.ckb2 = $c.stf.getObjectValue(ckb_2);
    scwin.ckb3 = $c.stf.getObjectValue(ckb_3);
    scwin.ckb4 = $c.stf.getObjectValue(ckb_4);
    scwin.ckb5 = $c.stf.getObjectValue(ckb_5);
    scwin.ckb6 = $c.stf.getObjectValue(ckb_6);
    scwin.ckb7 = $c.stf.getObjectValue(ckb_7);
    scwin.ckb8 = $c.stf.getObjectValue(ckb_8);
    scwin.ckb9 = $c.stf.getObjectValue(ckb_9);
    scwin.ckb10 = $c.stf.getObjectValue(ckb_10);
    scwin.ckb11 = $c.stf.getObjectValue(ckb_11);
    ckb12 = $c.stf.getObjectValue(ckb_12);
    if (scwin.ckb1 == "N" &&
        scwin.ckb2 == "N" &&
        scwin.ckb3 == "N" &&
        scwin.ckb4 == "N" &&
        scwin.ckb5 == "N" &&
        scwin.ckb6 == "N" &&
        scwin.ckb7 == "N" &&
        scwin.ckb8 == "N" &&
        scwin.ckb9 == "N" &&
        scwin.ckb10 == "N" &&
        scwin.ckb11 == "N" &&
        ckb12 == "N") {
        return false;
    }
};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // ISUR_APPL_ID  
    scwin.arrPar[1] = ""; // R 신청 

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_SetDefaultVal
 * 설명       : 화면의 기본값 세팅
 ***********************************************/
scwin.fn_SetDefaultVal = function() {
    $c.stf.fn_setFromToDate(3, edt_SDEL_DD, edt_EDEL_DD);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetDefaultVal();
    $c.stf.showObj(txb_param1, false);
    txb_STD_CD.focus();
};
scwin.btn_search_onclick = function() {
    if (scwin.fn_ChkValid() == false) {
        $c.win.alert("조회할 유가증권을 선택하세요.");
        return;
    }
    scwin.ins_search();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.img_SDEL_DD_onclick = function() {
    popUpCalendar2(edt_SDEL_DD);
};
scwin.img_EDEL_DD_onclick = function() {
    popUpCalendar2(edt_EDEL_DD);
};
scwin.txb_STD_CD_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_STD_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            if (scwin.fn_ChkValid() == false) {
                $c.win.alert("조회할 유가증권을 선택하세요.");
                return;
            } else {
                scwin.ins_search();
            }
        } else {

        }
    }
};
scwin.txb_ISUR_CD_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_ISUR_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            if (scwin.fn_ChkValid() == false) {
                $c.win.alert("조회할 유가증권을 선택하세요.");
                return;
            } else {
                scwin.ins_search();
            }
        } else {

        }
    }
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    var DEL_DD = dts_List.getCellData(row, "DEL_DD");
    DEL_DD = DEL_DD.replace("-", "");
    DEL_DD = DEL_DD.replace("-", "");
    //alert("DEL_DD " +DEL_DD);
    if (DEL_DD < "20140101") return; // asis 상품은 상세팝업 제공 안함 
    if (row == 0) return;
    var KND = dts_List.getCellData(row, "KND");
    var STD_CD = dts_List.getCellData(row, "STD_CD");
    if (KND == "지표" || KND == "선물옵션" || KND == "스트립") {
        txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
    } else {
        txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
    }
    fn_GetPar = fn_GetParam;
    ins_ViewIsuMaster(KND, STD_CD);
};
